public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns a list of sticker sets attached to a file, including regular, mask, and emoji sticker sets. Currently, only animations, photos, and videos can have attached sticker sets
    /// </summary>
    public Task<TdLib.TdApi.Objects.StickerSets> GetAttachedStickerSetsAsync(int fileId = default)
    {

           using var activity =  StartCallActivity("GetAttachedStickerSetsAsync", typeof(GetAttachedStickerSets).FullName ?? "GetAttachedStickerSetsAsync");

           try
           {
             return client.GetAttachedStickerSetsAsync(fileId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
